package com.game_manager.gm.machine;
import static com.game_manager.gm.machine.dto.StationPolicyDtos.*;import com.game_manager.gm.common.error.ApplicationException;import com.game_manager.gm.station.*;import java.time.*;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;
@Service @RequiredArgsConstructor public class StationConfigurationService {private final MachinePrincipalProvider principal;private final GamingStationProfileRepository stations;private final ApplicationProfileRepository profiles;private final ApplicationProfileEntryRepository entries;private final ApplicationDefinitionRepository definitions;private final StationPolicySigner signer;private final ObjectMapper json;private final Clock clock;
 @Transactional(readOnly=true)public SignedStationPolicy current(){MachinePrincipal machine=principal.require();GamingStationProfile station=stations.findByResourceId(machine.stationId()).filter(GamingStationProfile::isClientEnabled).orElseThrow(()->new ApplicationException(HttpStatus.NOT_FOUND,"Enabled station profile not found"));ApplicationProfile profile=profiles.findById(station.getApplicationProfileId()).filter(ApplicationProfile::isActive).orElseThrow(()->new ApplicationException(HttpStatus.UNPROCESSABLE_ENTITY,"Active application profile not found"));List<ApplicationProfileEntry> profileEntries=entries.findByProfileIdOrderByLaunchOrderAscIdAsc(profile.getId());Map<UUID,ApplicationDefinition> byId=definitions.findAllById(profileEntries.stream().map(ApplicationProfileEntry::getApplicationDefinitionId).toList()).stream().collect(Collectors.toMap(ApplicationDefinition::getId,Function.identity()));List<PolicyApplication> apps=profileEntries.stream().map(entry->{ApplicationDefinition app=Optional.ofNullable(byId.get(entry.getApplicationDefinitionId())).filter(ApplicationDefinition::isActive).orElseThrow(()->new ApplicationException(HttpStatus.UNPROCESSABLE_ENTITY,"Application profile contains an unavailable executable"));return new PolicyApplication(app.getCode(),app.getName(),app.getType(),app.getExecutablePath(),app.getPublisher(),app.getPublisherCertificateThumbprint(),app.getExecutableSha256(),app.getMinimumFileVersion(),entry.getArgumentsOverride()==null?app.getDefaultArguments():entry.getArgumentsOverride(),entry.isRequiredProcess(),entry.isAutoStart(),entry.getLaunchOrder(),entry.getDependencyGroup());}).toList();UnsignedStationPolicy policy=new UnsignedStationPolicy(machine.stationId(),profile.getId(),profile.getConfigurationVersion(),clock.instant(),apps);try{byte[] bytes=json.writeValueAsBytes(policy);return new SignedStationPolicy(Base64.getUrlEncoder().withoutPadding().encodeToString(bytes),"Ed25519",signer.keyId(),signer.sign(bytes));}catch(Exception e){if(e instanceof ApplicationException application)throw application;throw new ApplicationException(HttpStatus.INTERNAL_SERVER_ERROR,"Station policy could not be serialized");}}
}
